// One single query to the internal Jira for all candidates (instead of one per ticket)
const keys = $input.all().map(i => i.json.key).filter(Boolean);
if (!keys.length) return [];
const labels = keys.map(k => `"ext-${k}"`).join(', ');
return [{ json: {
  keys,
  jql: `project = ${$('Config').first().json.internal_project_key} AND labels in (${labels})`,
} }];

// Keep only client tickets that do not have an internal copy yet (idempotent sync)
const synced = new Set(
  $input.all().flatMap(i => i.json.fields?.labels ?? [])
);
return $('Search client Jira').all()
  .filter(i => !synced.has(`ext-${i.json.key}`))
  .map(i => {
    const f = i.json.fields;
    return { json: {
      key: i.json.key,
      url: `${i.json.self.split('/rest/')[0]}/browse/${i.json.key}`,
      summary: f.summary,
      description: f.description ?? '',
      reporter: f.reporter?.displayName ?? 'unknown',
      client_priority: f.priority?.name ?? 'unknown',
      created: f.created,
    } };
  });

