// Build the internal ticket: title with the client key, Jira wiki markup body, labels for traceability
const a = $input.item.json.output;
const t = $('Keep new tickets').item.json;
const cfg = $('Config').first().json;

const description = [
  `h3. Ticket del cliente: [${t.key}|${t.url}]`,
  `*Cliente:* ${cfg.client_name} · *Reportado por:* ${t.reporter} · *Prioridad del cliente:* ${t.client_priority}`,
  '',
  'h3. Contexto',
  ...a.context.map(c => `* ${c}`),
  '',
  'h3. Información a pedir al cliente',
  ...(a.missing_info.length ? a.missing_info.map(m => `* ${m}`) : ['_Nada pendiente_']),
  '',
  'h3. Descripción original',
  '{quote}', t.description || t.summary, '{quote}',
  '',
  '_Creado automáticamente por n8n + IA._',
].join('\n');

const slug = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-');

return { json: {
  client_key: t.key,
  client_url: t.url,
  summary: `${t.key} | ${a.title}`,
  description,
  issue_type_id: cfg.issue_type_ids[a.issue_type],
  priority_id: cfg.priority_ids[a.priority],
  labels: [`ext-${t.key}`, 'cliente-externo', slug(a.component)],
  ...a,
} };

